+cmd_submit() {
+    local domains=()
+    local sitemap_path="${DEFAULT_SITEMAP}"
+    local dry_run="false"
+    local headless="false"
+    local timeout="60000"
+    local file=""
+    
+    while [[ $# -gt 0 ]]; do
+        case "$1" in
+            --sitemap)
+                if [[ -z "${2:-}" || "$2" == -* ]]; then
+                    log_error "--sitemap requires a value"
+                    return 1
+                fi
+                sitemap_path="$2"
+                shift 2
+                ;;
+            --dry-run)
+                dry_run="true"
+                shift
+                ;;
+            --headless)
+                headless="true"
+                shift
+                ;;
+            --timeout)
+                if [[ -z "${2:-}" || "$2" == -* ]]; then
+                    log_error "--timeout requires a value"
+                    return 1
+                fi
+                if ! [[ "$2" =~ ^[0-9]+$ ]]; then
+                    log_error "--timeout must be a number (milliseconds)"
+                    return 1
+                fi
+                timeout="$2"
+                shift 2
+                ;;
+            --file)
+                if [[ -z "${2:-}" || "$2" == -* ]]; then
+                    log_error "--file requires a value"
+                    return 1
+                fi
+                file="$2"
+                shift 2
+                ;;
+            --skip-existing)
+                # Already handled by script logic
+                shift
+                ;;
+            -*)
+                log_error "Unknown option: $1"
+                return 1
+                ;;
+            *)
+                # Sanitize domain input
+                domains+=("$(sanitize_domain "$1")")
+                shift
+                ;;
+        esac
+    done
+    
+    # Read domains from file if specified
