log_info() { echo -e "${BLUE}[INFO]${NC} $1"; return 0; }
log_success() { echo -e "${GREEN}[SUCCESS]${NC} $1"; return 0; }
log_warn() { echo -e "${YELLOW}[WARN]${NC} $1"; return 0; }
log_error() { echo -e "${RED}[ERROR]${NC} $1" >&2; return 0; }
```

