+// Query
+const cursor = this.ctx.storage.sql.exec("SELECT * FROM users WHERE age > ?", 18);
+cursor.toArray()          // All rows
+cursor.one()              // 1 row or throw
+cursor.raw().toArray()    // [[1, 'Alice']]
